import 'package:flutter/material.dart';import 'package:skeletonizer/skeletonizer.dart';import '../../../Config/app_config.dart';import '../../../Config/Assets/images_test.dart';import 'card_product.dart';import '../../Resources/app_constants.dart';class BuildCustomGridBuilder extends StatefulWidget {  const BuildCustomGridBuilder({super.key, this.isSliver = false});  final bool isSliver;  @override  State<BuildCustomGridBuilder> createState() => _BuildCustomGridBuilderState();}class _BuildCustomGridBuilderState extends State<BuildCustomGridBuilder> {  bool _isLoading = true;  @override  void initState() {    super.initState();    Future.delayed(const Duration(seconds: 3), () {      if (mounted) {        setState(() {          _isLoading = false;        });      }    });  }  @override  Widget build(BuildContext context) {    final itemCount = _isLoading ? 2 : 13;    return widget.isSliver        ? SliverGrid.builder(            gridDelegate: AppConstants.gridDelegate,            itemCount: itemCount,            itemBuilder: _itemBuilder(),          )        : GridView.builder(            physics: AppConfig.physicsCustomScrollView,            gridDelegate: AppConstants.gridDelegate,            itemCount: itemCount,            itemBuilder: _itemBuilder(),          );  }  NullableIndexedWidgetBuilder _itemBuilder() => (context, index) {        return Skeletonizer(          enabled: _isLoading,          child: BuildCardProduct(            caption: "Lokman Sofa Premium",            imagePath: AppImagesTest.testPhoto,            price: r"$500",          ),        );      };}